/* ════════════════════════════════════════
   THEME SYSTEM — 9 themes via data-theme
   Default: chalk
════════════════════════════════════════ */

:root {
  --page-bg:      #dcdcda;
  --brief-bg:     #f7f7f4;
  --card-bg:      #ffffff;
  --text:         #26251e;
  --text-body:    #5a5852;
  --muted:        #8c8981;
  --border:       #e8e8e4;
  --accent:       #f54e00;
  --topbar-text:  #5a5852;
  --font-ui:      'Inter', 'Noto Sans SC', -apple-system, sans-serif;
  --font-display: 'Inter', 'Noto Sans SC', -apple-system, sans-serif;
  --font-mono:    var(--font-ui);
  --btn-bg:       #26251e;
  --btn-text:     #ffffff;
  --ghost-text:   #5a5852;
  --ghost-border: #e8e8e4;
  /* ── decorative / typographic tokens ── */
  --orb-1-opacity:  0;
  --orb-2-opacity:  0;
  --card-blur:      0px;
  --card-border:    var(--border);
  --bullet:         '·';
  --bullet-color:   var(--accent);
  --brief-radius:   12px;
  --title-size:     17px;
  --title-weight:   600;
  --body-size:      12px;
  --body-weight:    400;
  --hint-size:      10px;
  --label-weight:   600;
  /* ── 扩展字号 token（配合 --size-mult 等比缩放） ── */
  --label-size:     13px;   /* 卡片主题名（中文） */
  --label-en-size:  10px;   /* 卡片主题名（英文 / label span） */
  --meta-size:      12px;   /* topbar meta / brand */
  --sub-size:       11px;   /* 策略子项标题 s-item b */
  --small-size:     10px;   /* .sub 子分组标签 */
  --bullet-size:    14px;   /* 列表符号 */
  --size-mult:      1;
}

body[data-scale="sm"] { --size-mult: 1;    }
body[data-scale="md"] { --size-mult: 1.2;  }
body[data-scale="lg"] { --size-mult: 1.45; }

body[data-theme="chalk"] {
  --page-bg:      #dcdcda;
  --brief-bg:     #f7f7f4;
